using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class TimelineCanvasOperations
{
    private readonly ActorFileImportOperations _imports=new();private readonly ActorDefinitionOperations _definitions=new();private readonly ActorTransformationStateOperations _states=new();
    public bool preview_assets(Control owner,Vector2 position,string[] paths)
    {
        if(position.X<LabelWidth||position.Y<Header||!new Rect2(Vector2.Zero,owner.Size).HasPoint(position)){List(owner,"_asset_previews").Clear();owner.QueueRedraw();owner.EmitSignal("interaction_changed","");return false;}var model=Model(owner);var registry=owner.Get("registry").As<RefCounted>();if(!paths.SequenceEqual(owner.Get("_asset_paths").AsStringArray())){clear_asset_drag(owner);foreach(string path in paths){var type=_imports.type_for_path(path);var definition=_definitions.get_definition(registry,type.ToString()=="scene_instance"?new StringName("point_3d"):type);if(definition==null){clear_asset_drag(owner);return false;}var actor=_definitions.create_actor(definition,_imports.values_for_path(path,registry));actor.Set("section_id",model.Get("selected_section_id"));actor.Set("parent_id",model.Get("focused_actor_id"));double duration=type.ToString() is "audio" or "video" or "video_2d"?GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs").Call("length",actor).AsDouble():5;if(type.ToString()=="transform_image_2d"){var asset=_states.load_asset(ActorTransformationStates.Assets,actor);var document=asset["document"].As<Resource>();if(document==null)return false;duration=document.Get("duration").AsDouble();}if(type.ToString()=="scene_instance"){actor.Set("display_name",path.GetFile().GetBaseName());var scene=ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore);duration=_imports.scene_duration(ActorDataOperations.ScriptIs(scene,"res://scripts/actors/core/actor_scene_data.gd")?scene:null);}if(duration<=0)return false;List(owner,"_asset_templates").Add(new Settings{["actor"]=actor,["duration"]=duration,["path"]=path,["definition"]=definition});}owner.Set("_asset_paths",(string[])paths.Clone());}var previews=List(owner,"_asset_previews");previews.Clear();bool bypass=Input.IsKeyPressed(Key.Shift);double desired=snapped_playhead(owner,time_at(owner,position.X),bypass,false);int layer=layer_at(owner,position.Y);foreach(var item in List(owner,"_asset_templates")){var template=item.AsGodotDictionary();var actor=template["actor"].As<Resource>();actor.Set("section_id",model.Get("selected_section_id"));actor.Set("parent_id",model.Get("focused_actor_id"));double start=desired,duration=template["duration"].AsDouble();if(owner.Get("magnet_enabled").AsBool()&&!bypass)start+=magnetic_delta(owner,0,new GArray{start,start+duration},new GArray(),new GArray(),false,true);var neighbors=new List<Resource>();foreach(var clipValue in _timeline.section_clips(model)){var other=clipValue.As<Resource>();if(other.Get("layer").AsInt32()==layer&&_timeline.actors_obstruct(model,actor,_timeline.actor_for_id(model,other.Get("actor_id").AsString())))neighbors.Add(other);}neighbors.Sort((a,b)=>a.Get("start_time").AsDouble().CompareTo(b.Get("start_time").AsDouble()));foreach(var other in neighbors){double at=other.Get("start_time").AsDouble(),end=at+other.Get("duration").AsDouble();if(start<end&&start+duration>at)start=end;}var state=template.Duplicate();state["start"]=start;state["layer"]=layer;previews.Add(state);layer++;}owner.QueueRedraw();owner.EmitSignal("interaction_changed","Release to place • Drag outside to cancel • Shift disables snap");return previews.Count>0;
    }
    public bool can_drop_data(Control owner,Vector2 position,Variant data){var paths=dropped_paths(data);if(paths.Length==0){clear_asset_drag(owner);return false;}return preview_assets(owner,position,paths);}
    public void drop_data(Control owner,Vector2 position,Variant data){if(!can_drop_data(owner,position,data))return;var placements=List(owner,"_asset_previews").Duplicate();clear_asset_drag(owner);foreach(var item in placements){var placement=item.AsGodotDictionary();owner.EmitSignal("assets_dropped",new[]{placement["path"].AsString()},placement["start"],placement["layer"]);}}
}
